import java.io.*;
import java.math.*;
import java.util.*;

public class Main {

    static boolean check(long[] a, long[] b, long[] c, long[] d, long[] e, int n, int i) {
        long ai = a[i];
        long bi = b[i];
        long ci = c[i];
        long di = d[i];
        long ei = e[i];

        for (int j = 0; j < n; ++j) {
            if (j == i) continue;
            long ax = a[j] - ai;
            long bx = b[j] - bi;
            long cx = c[j] - ci;
            long dx = d[j] - di;
            long ex = e[j] - ei;

            for (int k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                long ay = a[k] - ai;
                long by = b[k] - bi;
                long cy = c[k] - ci;
                long dy = d[k] - di;
                long ey = e[k] - ei;

                if (ax * ay + bx * by + cx * cy + dx * dy + ex * ey > 0) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = reader.nextInt();
        if (n > 11) {
            pw.printf("0\n");
            pw.flush();
            pw.close();
            return;
        }

        long[] a = new long[n];
        long[] b = new long[n];
        long[] c = new long[n];
        long[] d = new long[n];
        long[] e = new long[n];

        for (int i = 0; i < n; ++i) {
            a[i] = reader.nextLong();
            b[i] = reader.nextLong();
            c[i] = reader.nextLong();
            d[i] = reader.nextLong();
            e[i] = reader.nextLong();
        }

        ArrayList<Integer> ret = new ArrayList<Integer>(11);
        for (int i = 0; i < n; ++i) {
            if (check(a, b, c, d, e, n, i)) ret.add(i + 1);
        }

        pw.printf("%d\n", ret.size());
        for (Integer x : ret) {
            pw.printf("%d\n", x);
        }
        pw.flush();
        pw.close();
    }

    public static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return "0";
                    tokenizer = new StringTokenizer(line);
                } catch (IOException ioe) {
                    throw new RuntimeException(ioe);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public Long nextLong() {
            return Long.parseLong(next());
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        public String nextLine() {
            String line = "";
            try {
                while (line.equals("")) {
                    line = reader.readLine();
                }
            } catch (IOException ioe) {
                throw new RuntimeException(ioe);
            }
            return line;
        }
    }
}
